/* READ ONLY Teradata SQL Assistant. Run each numbered SELECT separately.
Full populations, no account sample; no permanent tables/config/run changes.
Uses the analyst-confirmed numeric special list. Counts are account-month events.
Keep the source fixed and reconcile baseline counts to saved results first.
FLOAT casts precede arithmetic. NULL numeric outputs indicate invalid source grain;
absence of rows is not a pass. No individual account results should be uploaded.
*/
/* Dictionary row 42 maps types 2/3 to IO; row 395 defines IO_IND likewise. A mismatch requires source-alignment confirmation before calling it an error. Unknown codes are reported rather than interpreted as zero. */
WITH src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,EXTRACT(YEAR FROM FACT_DT)*12+EXTRACT(MONTH FROM FACT_DT) AS MK,
 NULLIF(TRIM(CAST(IO_IND AS VARCHAR(16))),'') AS IO,
 NULLIF(TRIM(CAST(REPAY_TYPE_CD AS VARCHAR(16))),'') AS RT,
 COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC
 FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE CAST(FACT_DT AS DATE) IN (DATE '2006-02-28',DATE '2006-03-31',DATE '2006-04-30',DATE '2009-09-30',DATE '2009-10-31',DATE '2009-11-30',DATE '2011-07-31',DATE '2011-08-31',DATE '2011-09-30',DATE '2013-11-30',DATE '2013-12-31',DATE '2014-01-31')),
 ctl AS (SELECT SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src),
 h AS (SELECT S.*,LAG(IO) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS PIO,LEAD(IO) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS NIO,LAG(RT) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS PRT,LEAD(RT) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS NRT,LAG(MK) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS PM,LEAD(MK) OVER (PARTITION BY AGMT_ID ORDER BY MK) AS NM FROM src S),
 f AS (SELECT H.*,
 CASE WHEN MK-PM=1 AND NM-MK=1 AND RT IN ('0','1','2','3','5','6') AND PRT IN ('0','1','2','3','5','6') AND NRT=PRT AND RT<>PRT THEN 1 ELSE 0 END AS RT_REV,
 CASE WHEN MK-PM=1 AND NM-MK=1 AND IO IN ('0','1') AND PIO IN ('0','1') AND NIO=PIO AND IO<>PIO THEN 1 ELSE 0 END AS IO_REV,
 CASE WHEN RT IN ('2','3') THEN '1' WHEN RT IN ('0','1','5','6') THEN '0' END AS EXPECTED_IO
 FROM h H WHERE POU_DT IN (DATE '2006-03-31',DATE '2009-10-31',DATE '2011-08-31',DATE '2013-12-31'))
SELECT POU_DT,
 CASE WHEN MAX(BAD)=0 THEN COUNT(*) END AS TOTAL_COUNT,
 CASE WHEN MAX(BAD)=0 THEN SUM(RT_REV) END AS REPAY_TYPE_RETURNS,
 CASE WHEN MAX(BAD)=0 THEN SUM(IO_REV) END AS IO_RETURNS,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN RT_REV=1 AND IO_REV=1 THEN 1 ELSE 0 END) END AS BOTH_RETURNS,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN EXPECTED_IO IS NOT NULL AND IO IN ('0','1') THEN 1 ELSE 0 END) END AS CURRENT_COMPARISONS,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN EXPECTED_IO IS NOT NULL AND IO IN ('0','1') AND EXPECTED_IO<>IO THEN 1 ELSE 0 END) END AS IO_CODE_MISMATCH,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN RT IS NULL THEN 1 ELSE 0 END) END AS CURRENT_REPAY_TYPE_MISSING,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN RT IS NOT NULL AND EXPECTED_IO IS NULL THEN 1 ELSE 0 END) END AS UNKNOWN_TYPE_CODE
FROM f CROSS JOIN ctl GROUP BY POU_DT ORDER BY POU_DT;
